css:
.pair{display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; margin-bottom:14px}
.pair figure{margin:0; display:grid; gap:4px}
.pair figcaption{font-family:var(--display); font-size:13px; color:var(--muted); text-align:center}
@media (max-width:520px){ .pair{grid-template-columns:minmax(0,1fr)} }
.lin-t{border-collapse:collapse; font-family:var(--mono); font-size:13.5px}
.lin-t td{padding:3px 10px 3px 0; white-space:nowrap}
.lin-t td:first-child{color:var(--muted)}
.lin-t tr.amb td{font-weight:600}
.note{font-size:14px; color:var(--muted); margin:0}
.comp{display:grid; gap:10px; border-top:1px dashed var(--rule); padding-top:12px}
.comp .kpick{flex-wrap:wrap}
.comp .kpick > span:first-child{min-width:4.5em}
.trow{display:flex; flex-wrap:wrap; gap:8px; align-items:center; font-family:var(--mono); font-size:13.5px}
.trow input.mi{width:56px}
.oplist{margin:0; padding-left:1.4em; font-family:var(--mono); font-size:13.5px; display:grid; gap:2px}
.oplist .none{list-style:none; margin-left:-1.4em; color:var(--muted)}
.rep-in{display:flex; flex-wrap:wrap; gap:14px 24px; align-items:flex-start}
.sl label{white-space:nowrap}
